import pytest

from api import API
from client import Client
from domain import Item
from store import Store


def make_api():
    return API(Store([Item('d', 'u', 'D'), Item('a', 'u', 'A'),
                      Item('b', 'v', 'B'), Item('c', 'u', 'C')]))


def test_pages_filter_sort_and_serialize():
    api = make_api()
    assert api.page('u') == (200, {
        'items': [{'id': 'a', 'text': 'A'}, {'id': 'c', 'text': 'C'}],
        'next_cursor': 'c',
    })
    assert api.page('u', cursor='c') == (200, {
        'items': [{'id': 'd', 'text': 'D'}], 'next_cursor': None,
    })
    assert api.page('u', limit=3)[1]['next_cursor'] is None
    assert api.page('u', cursor='b')[1]['items'][0]['id'] == 'c'
    for owner, cursor in [('missing', None), ('u', 'z')]:
        assert api.page(owner, cursor=cursor) == (200, {'items': [], 'next_cursor': None})


@pytest.mark.parametrize('limit', [True, False, 0, 6, -1, 2.0, '2', None])
def test_invalid_limits(limit):
    status, body = make_api().page('u', limit=limit)
    assert status == 400
    assert 'error' in body


@pytest.mark.parametrize('cursor', [False, 0, 2.0, [], {}])
def test_invalid_cursors(cursor):
    status, body = make_api().page('u', cursor=cursor)
    assert status == 400
    assert 'error' in body


def test_empty_cursor_and_live_insertions():
    api = API(Store([Item('', 'u', 'empty'), Item('b', 'u', 'B')]))
    assert api.page('u', limit=1)[1]['next_cursor'] == ''
    assert [item['id'] for item in Client(api, 'u').iter_items(1)] == ['', 'b']
    assert api.page('u', cursor='')[1]['items'] == [{'id': 'b', 'text': 'B'}]
    api.store.add(Item('a', 'u', 'A'))
    api.store.add(Item('c', 'u', 'C'))
    assert api.page('u', cursor='b')[1]['items'] == [{'id': 'c', 'text': 'C'}]
    assert len(Client(api, 'u').items()) == 4


def test_iterator_and_errors():
    assert list(Client(make_api(), 'u').iter_items()) == make_api().list('u')[1]
    with pytest.raises(ValueError) as error:
        list(Client(make_api(), 'u').iter_items(0))
    assert error.value.args == (400,)

    class FailingAPI:
        def page(self, owner, limit, cursor):
            if cursor is None:
                return 200, {'items': [{'id': 'a', 'text': 'A'}], 'next_cursor': 'a'}
            return 503, {'error': 'unavailable'}

    iterator = Client(FailingAPI(), 'u').iter_items()
    assert next(iterator) == {'id': 'a', 'text': 'A'}
    with pytest.raises(ValueError) as error:
        next(iterator)
    assert error.value.args == (503,)
